def dispatch_candidates(nodes, links, source, destination):
    # (total_cost, first_hops, rep_paths) for the equal lowest-cost paths
    # from source to destination, grouped by first hop. When the
    # destination is unreachable, total_cost is None and the other two
    # members are empty lists. Candidate first hops are deduplicated, sorted
    # by Unicode code point order, and each represented by the complete
    # path with the smallest node sequence.
    #
    # O(V^3) time (one O(V^2) Dijkstra per first hop, at most V of them)
    # and O(V^2) extra space (a path per hop per node), without ever
    # enumerating the exponentially many equal-cost simple paths.
